// Normalize Apify scraper output → TalentBridge collected_jobs schema.
// Supports common shapes from Indeed / LinkedIn / generic career-page actors.
const items = $input.all();
const pick = (o, ...keys) => keys.map(k => o?.[k]).find(v => v !== undefined && v !== null && v !== '');
const toIso = (v) => { if (!v) return null; const d = new Date(v); return isNaN(d.getTime()) ? null : d.toISOString(); };
const normSkills = (v) => {
  if (Array.isArray(v)) return v.map(String).map(s => s.trim()).filter(Boolean).slice(0, 60);
  if (typeof v === 'string') return v.split(/[,;|]/).map(s => s.trim()).filter(Boolean).slice(0, 60);
  return [];
};
const sourceFromUrl = (u) => {
  if (!u) return 'apify';
  try { const h = new URL(u).hostname.replace('www.', ''); return h.split('.')[0]; } catch { return 'apify'; }
};

const mapped = items.map(({ json }) => {
  const url = pick(json, 'url', 'jobUrl', 'job_url', 'link', 'externalUrl');
  return {
    job_title: pick(json, 'title', 'jobTitle', 'positionName', 'job_title') || 'Untitled',
    company_name: pick(json, 'company', 'companyName', 'employer', 'company_name') || 'Unknown',
    location: pick(json, 'location', 'jobLocation', 'place', 'city') || null,
    skills: normSkills(pick(json, 'skills', 'requiredSkills', 'tags', 'keywords')),
    job_url: url || null,
    source: pick(json, 'source', 'site') || sourceFromUrl(url),
    description: pick(json, 'description', 'descriptionText', 'jobDescription', 'snippet') || null,
    posted_date: toIso(pick(json, 'postedAt', 'datePosted', 'posted_date', 'publishedAt', 'date')),
    raw_payload: json,
  };
}).filter(r => r.job_title && r.company_name);

return [{ json: { jobs: mapped, count: mapped.length } }];
